/**
 * The conformance suite's main entity: every operator, order, paging,
 * select, count, soft delete and version case runs on it.
 *
 * `id` is generated by the store, whatever its type.
 */
export interface ConformanceItemInterface {
  id: string | number;
  name: string;
  rank: number | null;
  note: string | null;
  /** The remove date, or an ordinary one where soft delete is refused. */
  removedAt: Date | null;
  /** The optimistic-locking version column. */
  version: number;
}
